   239  
   240  function summarizeFeedback(feedback: Array<{ signal: "thumbs-up" | "thumbs-down" | "confused" }>): FeedbackSummary {
   241    const sampleSize = feedback.length;
   242    if (sampleSize === 0) {
   243      return { confusionRate: 0, satisfactionRate: 0, sampleSize };
   244    }
   245    const confused = feedback.filter((entry) => entry.signal === "confused").length;
   246    const satisfied = feedback.filter((entry) => entry.signal === "thumbs-up").length;
   247    return {
   248      confusionRate: confused / sampleSize,
   249      satisfactionRate: satisfied / sampleSize,
   250      sampleSize
   251    };
   252  }
