   403  function assertAutoImproveAllowed(state: AutoImproveState, force: boolean): void {
   404    if (force || !state.lastRunAt) return;
   405    const lastRunMs = Date.parse(state.lastRunAt);
   406    if (!Number.isFinite(lastRunMs)) return;
   407    const cooldownMs = 30 * 60 * 1000;
   408    const elapsedMs = Date.now() - lastRunMs;
   409    if (elapsedMs >= 0 && elapsedMs < cooldownMs) {
   410      const remainingMinutes = Math.ceil((cooldownMs - elapsedMs) / 60000);
   411      throw new Error(`auto-improve ran recently. Re-run with --force or wait ${remainingMinutes} minute(s).`);
   412    }
   413  }
