    44  function cellKey(descriptors: number[], resolution: number): string {
    45    return descriptors
    46      .map((d) => Math.min(Math.floor(d * resolution), resolution - 1))
    47      .join(",");
    48  }
    49  
    50  export function createGrid(descriptors: string[], resolution: number): MapElitesGrid {
    51    return {
    52      descriptors,
    53      resolution,
    54      cells: new Map()
    55    };
    56  }
    57  
    58  export function placeInGrid(
    59    grid: MapElitesGrid,
    60    policy: TeacherPolicy,
    61    weights: SimulationWeights,
    62    score: number,
    63    benchmark: BenchmarkResult,
    64    iteration: number
    65  ): boolean {
    66    const descVals = getDescriptorValues(policy, grid.descriptors);
    67    const key = cellKey(descVals, grid.resolution);
    68    const existing = grid.cells.get(key);
    69    if (!existing || score > existing.score) {
    70      grid.cells.set(key, { policy, weights, score, benchmark, iteration });
    71      return !existing;
    72    }
    73    return false;
    74  }
    75  
    76  function selectParent(grid: MapElitesGrid, prng: Prng): { policy: TeacherPolicy; weights: SimulationWeights } {
