     5  
     6  export interface LearnerTurnSignal {
     7    topic: string;
     8    signal: "thumbs-up" | "thumbs-down" | "confused";
     9    masteryEstimate: number;
    10    evidence: string;
    11  }
    12  
    13  const CONFUSION_PATTERNS = [
    14    /\b(confused|lost|stuck|unclear|not sure|don't understand|dont understand|doesn't make sense|doesnt make sense)\b/i,
    15    /\b(can you explain|what do you mean|why is|how does)\b/i
    16  ];
    17  
    18  const NEGATIVE_PATTERNS = [
    19    /\b(wrong|incorrect|not helpful|bad explanation|no,? that's not|still wrong)\b/i
    20  ];
    21  
    22  const POSITIVE_PATTERNS = [
    23    /\b(got it|makes sense|i understand|that helps|clear now|yes exactly|correct)\b/i
    24  ];
    25  
    26  export function inferLearnerTurnSignal(
    27    text: string,
    28    fallbackTopic = "general"
    29  ): LearnerTurnSignal | null {
    30    const compact = text.replace(/\s+/g, " ").trim();
    31    if (compact.length < 4) return null;
    32  
    33    const resolved = resolveTopic(inferTopic(compact, fallbackTopic));
    34    const signal =
    35      NEGATIVE_PATTERNS.some((pattern) => pattern.test(compact)) ? "thumbs-down" :
    36      CONFUSION_PATTERNS.some((pattern) => pattern.test(compact)) ? "confused" :
    37      POSITIVE_PATTERNS.some((pattern) => pattern.test(compact)) ? "thumbs-up" :
    38      null;
    39  
    40    if (!signal) return null;
    41  
    42    return {
    43      topic: resolved.slug,
    44      signal,
    45      masteryEstimate: signal === "thumbs-up" ? 0.75 : signal === "confused" ? 0.35 : 0.2,
    46      evidence: compact.slice(0, 240)
    47    };
    48  }
    49  
    50  export function learnerTurnSignalToOutcome(signal: LearnerTurnSignal, learnerId: string): RealLearnerOutcome {
    51    return {
    52      learnerId,
    53      topic: signal.topic,
    54      feedbackSignal: signal.signal,
    55      quizScore: null,
    56      sessionDurationMs: null,
    57      masteryEstimate: clamp(signal.masteryEstimate),
    58      outcomeScore: feedbackToOutcomeScore(signal.signal)
    59    };
    60  }
    61  
    62  function inferTopic(text: string, fallbackTopic: string): string {
    63    const lowered = text.toLowerCase();
    64    for (const token of lowered.match(/[a-z][a-z0-9-]{2,}/g) ?? []) {
    65      if (["confused", "understand", "explain", "wrong", "helpful", "clear", "still"].includes(token)) continue;
    66      const resolved = resolveTopic(token);
    67      if (resolved.slug !== token || token === fallbackTopic) return token;
    68    }
    69    return fallbackTopic;
    70  }

