    12  ): CapabilityDecision {
    13    const missing: Array<keyof SandboxRequirement> = [];
    14    const caps = sandbox.capabilities;
    15  
    16    if (requirement.secureIsolation && !caps.secureIsolation) missing.push("secureIsolation");
    17    if (requirement.nativeBinaries && !caps.nativeBinaries) missing.push("nativeBinaries");
    18    if (requirement.filesystem && !caps.filesystem) missing.push("filesystem");
    19    if (requirement.process && !caps.process) missing.push("process");
    20    if (requirement.sessions && !caps.sessions) missing.push("sessions");
    21    if (requirement.preview && !caps.preview) missing.push("preview");
    22    if (requirement.snapshots && !caps.snapshots) missing.push("snapshots");
    23    if (requirement.packageInstall && !caps.packageInstall) missing.push("packageInstall");
    24    if (requirement.outboundNetwork && caps.outboundNetwork !== true) missing.push("outboundNetwork");
    25    if (requirement.inboundNetwork && !caps.inboundNetwork) missing.push("inboundNetwork");
    26    if (requirement.secrets && caps.secrets !== requirement.secrets) missing.push("secrets");
    27  
    28    return { ok: missing.length === 0, missing };
    29  }
