    32    sandboxes: AgentSandbox[],
    33    requirement: SandboxRequirement = {}
    34  ): SandboxRoute {
    35    for (const sandbox of sandboxes) {
    36      const decision = checkCapabilities(sandbox, requirement);
    37      if (decision.ok) return { sandbox, decision };
    38    }
    39  
    40    if (sandboxes.length === 0) {
    41      throw unsupportedCapability(undefined, Object.keys(requirement) as Array<keyof SandboxRequirement>);
    42    }
    43  
    44    const local = sandboxes.find((sandbox) => sandbox.capabilities.browserLocal) ?? sandboxes[0]!;
    45    const decision = checkCapabilities(local, requirement);
    46    throw unsupportedCapability(
    47      local.kind,
    48      decision.missing,
    49      "Attach a remote Daytona/microsandbox adapter or relax the operation requirement."
    50    );
    51  }
    52  
    53  export async function withSandboxFallback<T>(
    54    local: AgentSandbox,
    55    remote: AgentSandbox | undefined,
    56    requirement: SandboxRequirement,
    57    operation: (sandbox: AgentSandbox) => Promise<T>
    58  ): Promise<{ sandbox: AgentSandbox; value: T; fallback: boolean }> {
    59    const localDecision = checkCapabilities(local, requirement);
    60    if (localDecision.ok) {
    61      return { sandbox: local, value: await operation(local), fallback: false };
    62    }
    63    if (!remote) {
    64      throw unsupportedCapability(
    65        local.kind,
    66        localDecision.missing,
    67        "No remote fallback sandbox is configured for this operation."
    68      );
    69    }
    70    const remoteDecision = checkCapabilities(remote, requirement);
    71    if (!remoteDecision.ok) {
