      return {
        content: [{ type: "text", text: `Auto-improve: ${result.baselineScore.toFixed(2)} → ${result.afterScore.toFixed(2)} (${verdict}, Δ${result.delta >= 0 ? "+" : ""}${result.delta.toFixed(2)})\nReport: ${relative(getCwd(), result.reportPath)}` }],
