    58  export function classifyTool(name: string): ToolSecurityDescriptor {
    59  	const risk = KEATING_TOOL_RISKS[name];
    60  	return risk ? { name, risk, known: true } : { name, risk: "code-execution", known: false, allowVoice: false };
    61  }
    62  
    63  export function evaluateToolPermission(request: ToolPermissionRequest): ToolPermissionDecision {
    64  	const { tool, surface, provenance } = request;
    65  	const reasons: string[] = [];
    66  	const untrusted = isUntrustedProvenance(provenance);
    67  	const independentlyAuthorized = hasIndependentUserAuthorization(provenance);
    68  	const secretBearing = tool.sensitiveArguments === true || containsLikelySecret(request.arguments);
    69  
    70  	if (tool.known === false) {
    71  		return decision("deny", tool.risk, ["Unknown tools are not part of Keating's callable surface."]);
    72  	}
    73  
    74  	if (surface === "voice" && (tool.allowVoice === false || NEVER_VOICE.has(tool.risk))) {
    75  		return decision("deny", tool.risk, ["This tool is not available from voice input."]);
    76  	}
    77  
    78  	if (surface === "voice" && secretBearing) {
    79  		return decision("deny", tool.risk, ["Secret-bearing arguments are not available from voice input."]);
    80  	}
    81  
    82  	if (untrusted && !independentlyAuthorized) {
    83  		if (tool.risk === "code-execution" || tool.risk === "destructive") {
    84  			return decision("deny", tool.risk, ["Untrusted web content cannot trigger code execution or destructive actions."]);
    85  		}
    86  	}
    87  
    88  	return decision("allow", tool.risk, reasons);
    89  }
    90  
    91  function decision(
    92  	outcome: ToolPermissionDecision["outcome"],
    93  	risk: ToolRiskClass,
    94  	reasons: readonly string[],
    95  ): ToolPermissionDecision {
    96  	return { outcome, risk, reasons };
    97  }

