     1  import type { ConversationEvent } from "../protocol";
     2  import { isConversationEvent, isUIAction } from "../protocol/validation";
     3  import { redactSecrets } from "../security/redaction";
     4  import type {
     5  	AppendResult,
     6  	ConversationEventStore,
     7  	EventStoreCheckpoint,
     8  	EventStoreDiagnostic,
     9  	PendingUIAction,
    10  	SessionReplay,
    11  	StorageLike,
    12  	DurableProjectionOptions,
    13  } from "./types";
    14  
    15  interface StoredSession {
    16  	format: 1;
    17  	events: ConversationEvent[];
    18  	pendingActions: PendingUIAction[];
    19  	checkpoint?: EventStoreCheckpoint;
    20  }
    21  
    22  const emptySession = (): StoredSession => ({ format: 1, events: [], pendingActions: [] });
    23  
    24  function isPendingAction(value: unknown): value is PendingUIAction {
    25  	if (!value || typeof value !== "object") return false;
    26  	const pending = value as Partial<PendingUIAction>;
    27  	return typeof pending.sessionId === "string" && !!pending.sessionId
    28  		&& typeof pending.runId === "string" && !!pending.runId
    29  		&& typeof pending.createdAt === "string" && Number.isFinite(Date.parse(pending.createdAt))
    30  		&& isUIAction(pending.action);
    31  }
    32  
    33  /** Produces the privacy-safe event representation written to durable storage. */
    34  export function projectDurableEvent(event: ConversationEvent, options: DurableProjectionOptions = {}): ConversationEvent | null {
    35  	if (!isConversationEvent(event)) return null;
    36  	if (event.type === "audio.delta") return null;
    37  	if (event.type === "transcript.delta" && !options.persistTranscripts) return null;
    38  
    39  	let projected: ConversationEvent = event;
    40  	if (event.type === "tool.requested") projected = { ...event, payload: { ...event.payload, arguments: {} } };
    41  	else if (event.type === "tool.progress") projected = { ...event, payload: { ...event.payload, update: null } };
    42  	else if (event.type === "tool.completed") projected = { ...event, payload: { ...event.payload, result: null } };
    43  
    44  	const redacted = { ...projected, payload: redactSecrets(projected.payload) } as ConversationEvent;
    45  	return isConversationEvent(redacted) ? redacted : null;
    46  }
    47  
    48  function projectPendingAction(pending: PendingUIAction): PendingUIAction | null {
    49  	if (!isPendingAction(pending)) return null;
    50  	const action = redactSecrets(pending.action) as PendingUIAction["action"];
    51  	return isUIAction(action) ? { ...pending, action } : null;
    52  }
    53  
    54  function normalizeSession(value: unknown, key: string, diagnostics: EventStoreDiagnostic[]): StoredSession {
    55  	if (!value || typeof value !== "object") {
    56  		diagnostics.push({ code: "corrupt-record", key, message: "Session record is not an object" });
    57  		return emptySession();
    58  	}
    59  	const record = value as Partial<StoredSession>;
    60  	if (record.format !== 1 || !Array.isArray(record.events) || !Array.isArray(record.pendingActions)) {
    61  		diagnostics.push({ code: "corrupt-record", key, message: "Session record has an unsupported shape" });
    62  		return emptySession();
    63  	}
    64  	const events = record.events.filter((event) => {
    65  		const valid = isConversationEvent(event);
    66  		if (!valid) diagnostics.push({ code: "invalid-event", key, message: "Ignored an invalid stored event" });
    67  		return valid;
    68  	});
    69  	const pendingActions = record.pendingActions.filter((action) => {
    70  		const valid = isPendingAction(action);
    71  		if (!valid) diagnostics.push({ code: "corrupt-record", key, message: "Ignored an invalid pending UI action" });
    72  		return valid;
    73  	});
    74  	return { format: 1, events, pendingActions, checkpoint: record.checkpoint };
    75  }
    76  
    77  export interface StorageEventStoreOptions {
    78  	prefix?: string;
    79  	onDiagnostic?: (diagnostic: EventStoreDiagnostic) => void;
    80  	durable?: DurableProjectionOptions;
    81  }
    82  
    83  export class StorageConversationEventStore implements ConversationEventStore {
    84  	private readonly prefix: string;
    85  	private readonly onDiagnostic?: (diagnostic: EventStoreDiagnostic) => void;
    86  	private readonly durable: DurableProjectionOptions;
    87  
    88  	constructor(private readonly storage: StorageLike, options: StorageEventStoreOptions = {}) {
    89  		this.prefix = options.prefix ?? "keating:conversation-events:v1";
    90  		this.onDiagnostic = options.onDiagnostic;
    91  		this.durable = options.durable ?? {};
    92  	}
    93  
    94  	append(event: ConversationEvent): AppendResult {
    95  		if (!isConversationEvent(event)) {
    96  			this.diagnose({ code: "invalid-event", key: this.sessionKey(String((event as { sessionId?: unknown }).sessionId ?? "invalid")), message: "Rejected an invalid event" });
    97  			return { appended: false, eventCount: 0 };
    98  		}
    99  		const session = this.read(event.sessionId).record;
   100  		if (session.events.some((existing) => existing.id === event.id)) {
   101  			return { appended: false, eventCount: session.events.length };
   102  		}
   103  		const durableEvent = projectDurableEvent(event, this.durable);
   104  		if (!durableEvent) return { appended: false, eventCount: session.events.length };
   105  		session.events.push(durableEvent);
   106  		session.events.sort((a, b) => a.sequence - b.sequence || a.timestamp.localeCompare(b.timestamp));
   107  		this.write(event.sessionId, session);
   108  		this.addToIndex(event.sessionId);
   109  		return { appended: true, eventCount: session.events.length };
   110  	}
   111  
   112  	appendMany(events: readonly ConversationEvent[]): { appended: number; eventCount: number } {
   113  		let appended = 0;
   114  		let eventCount = 0;
   115  		for (const event of events) {
   116  			const result = this.append(event);
   117  			if (result.appended) appended++;
   118  			eventCount = result.eventCount;
   119  		}
   120  		return { appended, eventCount };
   121  	}
   122  
   123  	replay(sessionId: string): SessionReplay {
   124  		const { record, diagnostics } = this.read(sessionId);
   125  		return {
   126  			sessionId,
   127  			events: [...record.events].sort((a, b) => a.sequence - b.sequence || a.timestamp.localeCompare(b.timestamp)),
   128  			checkpoint: record.checkpoint,
   129  			diagnostics,
   130  		};
   131  	}
   132  
   133  	listSessionIds(): string[] {
   134  		const key = this.indexKey();
   135  		try {
   136  			const raw = this.storage.getItem(key);
   137  			if (raw === null) return [];
   138  			const parsed: unknown = JSON.parse(raw);
   139  			if (Array.isArray(parsed) && parsed.every((item) => typeof item === "string")) return [...new Set(parsed)].sort();
   140  			this.diagnose({ code: "corrupt-record", key, message: "Session index has an unsupported shape" });
   141  		} catch (error) {
   142  			this.diagnose({ code: "corrupt-record", key, message: error instanceof Error ? error.message : String(error) });
   143  		}
   144  		return [];
   145  	}
   146  
   147  	putPendingAction(action: PendingUIAction): void {
   148  		const durableAction = projectPendingAction(action);
   149  		if (!durableAction) {
   150  			this.diagnose({ code: "corrupt-record", key: this.sessionKey(String((action as { sessionId?: unknown }).sessionId ?? "invalid")), message: "Rejected an invalid pending UI action" });
   151  			return;
   152  		}
   153  		const session = this.read(durableAction.sessionId).record;
   154  		const index = session.pendingActions.findIndex((item) => item.action.id === durableAction.action.id);
   155  		if (index >= 0) session.pendingActions[index] = durableAction;
   156  		else session.pendingActions.push(durableAction);
   157  		this.write(durableAction.sessionId, session);
   158  		this.addToIndex(durableAction.sessionId);
   159  	}
   160  
   161  	listPendingActions(sessionId: string): PendingUIAction[] {
   162  		return [...this.read(sessionId).record.pendingActions].sort((a, b) => a.createdAt.localeCompare(b.createdAt));
   163  	}
   164  
   165  	removePendingAction(sessionId: string, actionId: string): boolean {
   166  		const session = this.read(sessionId).record;
   167  		const next = session.pendingActions.filter((item) => item.action.id !== actionId);
   168  		if (next.length === session.pendingActions.length) return false;
   169  		session.pendingActions = next;
   170  		this.write(sessionId, session);
   171  		return true;
   172  	}
   173  
   174  	compact(sessionId: string, checkpoint: EventStoreCheckpoint): SessionReplay {
   175  		const session = this.read(sessionId).record;
   176  		session.events = session.events.filter((event) => event.sequence > checkpoint.throughSequence);
   177  		session.checkpoint = checkpoint;
   178  		this.write(sessionId, session);
   179  		this.addToIndex(sessionId);
   180  		return this.replay(sessionId);
   181  	}
   182  
   183  	clearSession(sessionId: string): void {
   184  		this.storage.removeItem(this.sessionKey(sessionId));
   185  		this.writeIndex(this.listSessionIds().filter((id) => id !== sessionId));
   186  	}
   187  
   188  	private read(sessionId: string): { record: StoredSession; diagnostics: EventStoreDiagnostic[] } {
   189  		const key = this.sessionKey(sessionId);
   190  		const diagnostics: EventStoreDiagnostic[] = [];
   191  		try {
   192  			const raw = this.storage.getItem(key);
   193  			if (raw === null) return { record: emptySession(), diagnostics };
   194  			const record = normalizeSession(JSON.parse(raw) as unknown, key, diagnostics);
   195  			for (const diagnostic of diagnostics) this.diagnose(diagnostic);
   196  			return { record, diagnostics };
   197  		} catch (error) {
   198  			const diagnostic: EventStoreDiagnostic = {
   199  				code: "corrupt-record",
   200  				key,
   201  				message: error instanceof Error ? error.message : String(error),
   202  			};
   203  			diagnostics.push(diagnostic);
   204  			this.diagnose(diagnostic);
   205  			return { record: emptySession(), diagnostics };
   206  		}
   207  	}
   208  
   209  	private write(sessionId: string, record: StoredSession): void {
   210  		this.storage.setItem(this.sessionKey(sessionId), JSON.stringify(record));
   211  	}
   212  
   213  	private addToIndex(sessionId: string): void {
   214  		const ids = this.listSessionIds();
   215  		if (!ids.includes(sessionId)) this.writeIndex([...ids, sessionId].sort());
   216  	}
   217  
   218  	private writeIndex(ids: string[]): void {
   219  		this.storage.setItem(this.indexKey(), JSON.stringify(ids));
   220  	}
   221  
   222  	private sessionKey(sessionId: string): string {
   223  		return `${this.prefix}:session:${encodeURIComponent(sessionId)}`;
   224  	}
   225  
   226  	private indexKey(): string {
   227  		return `${this.prefix}:sessions`;
   228  	}
   229  
   230  	private diagnose(diagnostic: EventStoreDiagnostic): void {
   231  		this.onDiagnostic?.(diagnostic);
   232  	}
   233  }

