     1  /**
     2   * The deliberately small, vendor-neutral record Keating may export about a
     3   * completed local evaluation. It is never a copy of an artifact, prompt,
     4   * topic, learner record, path, or error message.
     5   */
     6  export const EVALUATION_OBSERVATION_VERSION = 1 as const;
     7  
     8  export type EvaluationOperation =
     9    | "benchmark"
    10    | "policy_evolution"
    11    | "prompt_eval"
    12    | "prompt_evolution"
    13    | "auto_improve";
    14  
    15  export type EvaluationEngine = "deterministic" | "heuristic" | "llm" | "learner-feedback";
    16  export type EvaluationStatus = "success" | "error" | "rejected" | "rolled_back";
    17  export type EvaluationSurface = "cli" | "pi" | "mcp";
    18  
    19  export interface EvaluationObservationV1 {
    20    schemaVersion: typeof EVALUATION_OBSERVATION_VERSION;
    21    operation: EvaluationOperation;
    22    engine: EvaluationEngine;
    23    status: EvaluationStatus;
    24    suite: string;
    25    duration_ms: number;
    26    score?: number;
    27    before_score?: number;
    28    after_score?: number;
    29    outcome_count?: number;
    30    candidate_count?: number;
    31    provider?: string;
    32    model?: string;
    33    error_category?: string;
    34    app_version: string;
    35    surface: EvaluationSurface;
    36  }
    37  
    38  export interface ArizeAvailability {
    39    enabled: boolean;
    40    reason:
    41      | "enabled"
    42      | "disabled"
    43      | "missing_api_key"
    44      | "missing_space_id"
    45      | "invalid_endpoint"
    46      | "invalid_project_name";
    47    evaluationContentEnabled: boolean;
    48    maxContentChars: number;
    49    rateLimitPerMinute: number;
    50  }

