     1  import { SpanStatusCode } from "@opentelemetry/api";
     2  import { OTLPTraceExporter } from "@opentelemetry/exporter-trace-otlp-proto";
     3  import { resourceFromAttributes } from "@opentelemetry/resources";
     4  import { SimpleSpanProcessor } from "@opentelemetry/sdk-trace-base";
     5  import { NodeTracerProvider } from "@opentelemetry/sdk-trace-node";
     6  
     7  import { readArizeConfig } from "./config.js";
     8  import type { EvaluationObservationV1 } from "./types.js";
     9  
    10  type ObservationExporter = (observation: EvaluationObservationV1) => Promise<void>;
    11  
    12  export interface ProviderCompletionObservation {
    13    provider: string;
    14    model: string;
    15    duration_ms: number;
    16    status: "success" | "error";
    17    parse_outcome: "not_requested" | "success" | "invalid";
    18    error_category?: string;
    19    app_version: string;
    20    surface: "cli" | "pi" | "mcp";
    21  }
    22  
    23  let testExporter: ObservationExporter | undefined;
    24  
    25  export function setEvaluationObservationExporterForTests(exporter?: ObservationExporter): void {
    26    testExporter = exporter;
    27  }
    28  
    29  function attributesFor(observation: EvaluationObservationV1): Record<string, string | number | boolean> {
    30    const attributes: Record<string, string | number | boolean> = {
    31      "openinference.span.kind": "EVALUATOR",
    32      "keating.schema.version": observation.schemaVersion,
    33      "keating.evidence.engine": observation.engine,
    34      "keating.evaluation.status": observation.status,
    35      "keating.evaluation.suite": observation.suite,
    36      "keating.duration_ms": observation.duration_ms,
    37      "keating.app.version": observation.app_version,
    38      "keating.surface": observation.surface,
    39    };
    40    for (const key of ["score", "before_score", "after_score", "outcome_count", "candidate_count"] as const) {
    41      if (observation[key] !== undefined) attributes[`keating.evaluation.${key}`] = observation[key];
    42    }
    43    if (observation.provider) attributes["llm.provider"] = observation.provider;
    44    if (observation.model) attributes["llm.model_name"] = observation.model;
    45    if (observation.error_category) attributes["keating.error.category"] = observation.error_category;
    46    return attributes;
    47  }
    48  
    49  async function exportToOtlp(observation: EvaluationObservationV1): Promise<void> {
    50    const config = readArizeConfig();
    51    if (!config.enabled || !config.apiKey || !config.spaceId || !config.endpoint || !config.projectName) return;
    52  
    53    const exporter = new OTLPTraceExporter({
    54      url: config.endpoint,
    55      headers: { "arize-space-id": config.spaceId, "arize-api-key": config.apiKey },
    56    });
    57    const provider = new NodeTracerProvider({
    58      resource: resourceFromAttributes({ "openinference.project.name": config.projectName }),
    59      spanProcessors: [new SimpleSpanProcessor(exporter)],
    60    });
    61    const endedAt = Date.now();
    62    const startedAt = endedAt - observation.duration_ms;
    63    const span = provider.getTracer("keating.arize").startSpan(`keating.evaluation.${observation.operation}`, { startTime: startedAt });
    64    span.setAttributes(attributesFor(observation));
    65    if (observation.status !== "success") span.setStatus({ code: SpanStatusCode.ERROR, message: observation.error_category ?? observation.status });
    66    span.end(endedAt);
    67    try {
    68      await provider.forceFlush();
    69    } finally {
    70      await provider.shutdown();
    71    }
    72  }
    73  
    74  async function exportProviderToOtlp(observation: ProviderCompletionObservation): Promise<void> {
    75    const config = readArizeConfig();
    76    if (!config.enabled || !config.apiKey || !config.spaceId || !config.endpoint || !config.projectName) return;
    77    const exporter = new OTLPTraceExporter({
    78      url: config.endpoint,
    79      headers: { "arize-space-id": config.spaceId, "arize-api-key": config.apiKey },
    80    });
    81    const provider = new NodeTracerProvider({
    82      resource: resourceFromAttributes({ "openinference.project.name": config.projectName }),
    83      spanProcessors: [new SimpleSpanProcessor(exporter)],
    84    });
    85    const endedAt = Date.now();
    86    const startedAt = endedAt - observation.duration_ms;
    87    const span = provider.getTracer("keating.arize").startSpan("keating.llm.completion", { startTime: startedAt });
    88    span.setAttributes({
    89      "openinference.span.kind": "LLM",
    90      "llm.provider": observation.provider,
    91      "llm.model_name": observation.model,
    92      "keating.duration_ms": observation.duration_ms,
    93      "keating.parse.outcome": observation.parse_outcome,
    94      "keating.app.version": observation.app_version,
    95      "keating.surface": observation.surface,
    96      ...(observation.error_category ? { "keating.error.category": observation.error_category } : {}),
    97    });
    98    if (observation.status === "error") span.setStatus({ code: SpanStatusCode.ERROR, message: observation.error_category ?? "error" });
    99    span.end(endedAt);
   100    try {
   101      await provider.forceFlush();
   102    } finally {
   103      await provider.shutdown();
   104    }
   105  }
   106  
   107  /** Best effort by contract: a telemetry outage must never alter the caller. */
   108  export async function exportEvaluationObservation(observation: EvaluationObservationV1): Promise<void> {
   109    try {
   110      if (testExporter) await testExporter(observation);
   111      else await exportToOtlp(observation);
   112    } catch {
   113      // Intentionally opaque: raw transport/provider errors may contain secrets.
   114    }
   115  }
   116  
   117  export async function exportProviderCompletion(observation: ProviderCompletionObservation): Promise<void> {
   118    try {
   119      await exportProviderToOtlp(observation);
   120    } catch {
   121      // Provider traces are observational and cannot make a completion fail.
   122    }
   123  }
   124  
   125  export function classifyObservationError(error: unknown): string {
   126    if (error instanceof Error && /not ready|cooldown/i.test(error.message)) return "rejected";
   127    if (error instanceof Error && /parse|json/i.test(error.message)) return "parse";
   128    return "operation_failed";
   129  }

