 983  export function inferBrowserLearnerTurnSignal(text: string, fallbackTopic = "general"): BrowserLearnerTurnSignal | null {
 984  	const compact = text.replace(/\s+/g, " ").trim();
 985  	if (compact.length < 4) return null;
 986  	const lowered = compact.toLowerCase();
 987  	const signal =
 988  		/\b(wrong|incorrect|not helpful|bad explanation|no,? that's not|still wrong)\b/i.test(lowered) ? "thumbs-down" :
 989  		/\b(confused|lost|stuck|unclear|not sure|don't understand|dont understand|doesn't make sense|doesnt make sense|can you explain|what do you mean|why is|how does)\b/i.test(lowered) ? "confused" :
 990  		/\b(got it|makes sense|i understand|that helps|clear now|yes exactly|correct)\b/i.test(lowered) ? "thumbs-up" :
 991  		null;
 992  	if (!signal) return null;
 993  	const resolved = resolveTopic(fallbackTopic);
 994  	return {
 995  		topic: resolved.slug,
 996  		signal,
 997  		masteryEstimate: signal === "thumbs-up" ? 0.75 : signal === "confused" ? 0.35 : 0.2,
 998  		evidence: compact.slice(0, 240),
 999  	};
1000  }
1001  
1002  export function extractBrowserOutcomes(feedbackHistory: Array<{ topic: string; signal: "thumbs-up" | "thumbs-down" | "confused" }>, topicsExplored: string[]): BrowserLearnerOutcome[] {
1003  	return feedbackHistory.map((fb) => ({
1004  		topic: resolveTopic(fb.topic).slug,
1005  		feedbackSignal: fb.signal,
1006  		masteryEstimate: topicsExplored.includes(fb.topic) ? 0.6 : 0.4,
1007  		outcomeScore: feedbackToOutcomeScore(fb.signal),
1008  	}));
1009  }
1010  
1011  export interface BenchSessionSample {
1012  	id: string;
1013  	title: string;
1014  	model?: { provider?: string; id?: string; name?: string };
1015  	messages: unknown[];
1016  }
1017  
1018  export function benchModelLabel(model?: BenchSessionSample["model"]): string {
1019  	if (!model) return "unattributed";
1020  	const name = model.name ?? model.id;
1021  	if (!name) return model.provider ?? "unattributed";
1022  	return model.provider ? `${model.provider}/${name}` : name;
1023  }
1024  
1025  function benchMessageText(message: unknown): string {
1026  	const content = (message as { content?: unknown }).content;
1027  	if (typeof content === "string") return content.trim();
1028  	if (!Array.isArray(content)) return "";
1029  	return content
1030  		.map((item) => {
1031  			if (typeof item === "string") return item;
1032  			if (item && typeof item === "object" && typeof (item as { text?: unknown }).text === "string") {
1033  				return (item as { text: string }).text;
1034  			}
1035  			return "";
1036  		})
1037  		.filter(Boolean)
1038  		.join(" ")
1039  		.trim();
1040  }
1041  
1042  export function extractSessionTurnOutcomes(samples: BenchSessionSample[]): BrowserLearnerOutcome[] {
1043  	const outcomes: BrowserLearnerOutcome[] = [];
1044  	for (const sample of samples) {
1045  		const model = benchModelLabel(sample.model);
1046  		for (const message of sample.messages) {
1047  			if (!message || typeof message !== "object") continue;
1048  			const role = (message as { role?: unknown }).role;
1049  			if (role !== "user" && role !== "user-with-attachments") continue;
1050  			const text = benchMessageText(message);
1051  			if (!text) continue;
1052  			const inferred = inferBrowserLearnerTurnSignal(text, sample.title);
1053  			if (!inferred || inferred.topic === "general") continue;
1054  			outcomes.push({
1055  				topic: inferred.topic,
1056  				feedbackSignal: inferred.signal,
1057  				masteryEstimate: inferred.masteryEstimate,
1058  				outcomeScore: feedbackToOutcomeScore(inferred.signal),
1059  				model,
1060  			});
1061  		}
1062  	}
1063  	return outcomes;
1064  }
1065  
1066  export function quizRecordsToOutcomes(
1067  	records: Array<{ topic: string; score: number; totalQuestions: number; sessionId?: string }>,
1068  	modelBySessionId?: Map<string, string>
1069  ): BrowserLearnerOutcome[] {
1070  	const outcomes: BrowserLearnerOutcome[] = [];
1071  	for (const record of records) {
1072  		if (!(record.totalQuestions > 0)) continue;
1073  		const score = clamp(record.score / record.totalQuestions);
1074  		outcomes.push({
1075  			topic: resolveTopic(record.topic).slug,
1076  			feedbackSignal: score >= 0.75 ? "thumbs-up" : score < 0.4 ? "thumbs-down" : "confused",
1077  			quizScore: score,
1078  			masteryEstimate: score,
1079  			outcomeScore: score,
1080  			model: (record.sessionId && modelBySessionId?.get(record.sessionId)) || "unattributed",
1081  		});
1082  	}
1083  	return outcomes;
1084  }
