 27  export function createOutcomeCollector(
 28  	storage: KeatingStorage,
 29  	getSessionSamples?: KeatingToolsOptions["getSessionSamples"],
 30  ): OutcomeCollector {
 31  	return async (): Promise<BrowserLearnerOutcome[]> => {
 32  		const learnerState = await storage.getLearnerState();
 33  		const samples = getSessionSamples
 34  			? await getSessionSamples().catch(() => [] as BenchSessionSample[])
 35  			: [];
 36  		const modelBySessionId = new Map(
 37  			samples.filter((sample) => sample.id).map((sample) => [sample.id, benchModelLabel(sample.model)]),
 38  		);
 39  		const quizRecords = await storage.getQuizResults().catch(() => []);
 40  		return [
 41  			...extractBrowserOutcomes(learnerState.feedbackHistory, learnerState.topicsExplored),
 42  			...extractSessionTurnOutcomes(samples),
 43  			...quizRecordsToOutcomes(quizRecords, modelBySessionId),
 44  		];
 45  	};
 46  }
 47  
