 59  				const realOutcomes = await collectRealOutcomes();
 60  
 61  				const result = runBenchmarkSuite(teacherPolicy, topic, 20260401, 3, DEFAULT_WEIGHTS, realOutcomes);
 62  				const perModel = benchmarkPerModel(teacherPolicy, realOutcomes, topic);
 63  				const perModelReport = perModelBreakdownToMarkdown(perModel);
 64  				const report = perModelReport
 65  					? `${benchmarkToMarkdown(result).trimEnd()}\n\n${perModelReport}\n`
 66  					: benchmarkToMarkdown(result);
 67  
 68  				const saved = await storage.saveBenchmark(
 69  					result.overallScore,
 70  					report,
 71  					topic,
 72  					JSON.stringify({ ...result.trace, perModel }, null, 2)
 73  				);
 74  
